public static boolean exists(BinNode<Integer> t, int x) {
    if (t == null) {
        return false;
    }
    if (t.getValue() == x) {
        return true;
    }
    return exists(t.getLeft(), x) || exists(t.getRight(), x);
}

public static int countEven(BinNode<Integer> t) {
    if (t == null) {
        return 0;
    }
    int here = t.getValue() % 2 == 0 ? 1 : 0;
    return here + countEven(t.getLeft()) + countEven(t.getRight());
}

